contracts/Deployer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./AuditLog.sol";
import "./PatientRegistry.sol";
import "./ProviderRegistry.sol";
import "./AccessControl.sol";
import "./RecordManager.sol";

contract Deployer {
    AuditLog         public auditLog;
    PatientRegistry  public patientRegistry;
    ProviderRegistry public providerRegistry;
    AccessControl    public accessControl;
    RecordManager    public recordManager;

    address public hospitalAdmin;

    constructor(address _hospitalAdmin) {
        require(_hospitalAdmin != address(0), "Deployer: zero hospitalAdmin");
        hospitalAdmin = _hospitalAdmin;

        // AuditLog has no dependencies, registries are
        // independent, AccessControl depends on the two registries + audit
        // log, RecordManager depends on AccessControl + audit log.
        auditLog         = new AuditLog();
        patientRegistry  = new PatientRegistry();
        providerRegistry = new ProviderRegistry(_hospitalAdmin);
        accessControl    = new AccessControl(
            address(patientRegistry),
            address(providerRegistry),
            address(auditLog)
        );
        recordManager    = new RecordManager(
            address(accessControl),
            address(auditLog)
        );

        // Austhrosie other contracts that need to write to it.
        auditLog.authorise(address(accessControl));
        auditLog.authorise(address(recordManager));

        // Hand AuditLog ownership over to the hospital admin so they can
        // add/remove future writers without involving the deployer EOA.
        auditLog.transferOwnership(_hospitalAdmin);
    }

    function systemStatus() external view returns (
            address _hospitalAdmin,
            address _auditLogOwner,
            uint256 _patientCount,
            uint256 _providerCount,
            uint256 _recordCount,
            uint256 _auditLogCount
        )
    {
        _hospitalAdmin = hospitalAdmin;
        _auditLogOwner = auditLog.owner();
        _patientCount  = patientRegistry.patientCount();
        _providerCount = providerRegistry.providerCount();
        _recordCount   = recordManager.recordCount();
        _auditLogCount = auditLog.getLogCount();
    }
}

contracts/RecordManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IAccessControl {
    function checkAccess(address patient, address provider) external view returns (bool);
}

interface IAuditLogRM {
    function logEvent(address actor, address subject, address counterparty, string calldata action) external;
}

contract RecordManager {
    IAccessControl public accessControl;
    IAuditLogRM    public auditLog;

    // Comments suggest potential fields... look into these if enough time
    struct Record {
        address provider;
        address patient;
        string  cid;             // CID of encrypted file on IPFS
        uint256 timestamp; 
        uint256 previousVersion; // 0 if original
        bool    superseded;      // true if not newest version
    }

    Record[] private records;
    mapping(address => uint256[]) private patientRecords; // patient => record ids

    event RecordUploaded(
        address indexed patient,
        address indexed provider,
        string cid,
        uint256 timestamp
    );
    event RecordUpdated(
        uint256 indexed newId,
        uint256 indexed previousId,
        address indexed patient,
        string cid,
        uint256 timestamp
    );

    constructor(address _accessControl, address _auditLog) {
        require(_accessControl != address(0), "RecordManager: zero accessControl");
        require(_auditLog != address(0), "RecordManager: zero auditLog");
        accessControl = IAccessControl(_accessControl);
        auditLog      = IAuditLogRM(_auditLog);
    }

    // TODO: functions

    function uploadRecord(address patient, string calldata cid) external returns (uint256) {
        // Check access permissions
        require(accessControl.checkAccess(patient, msg.sender), "RecordManager: not authorized");
        
        records.push(Record({
            provider: msg.sender,
            patient: patient,
            cid: cid,
            timestamp: block.timestamp,
            previousVersion: 0,
            superseded: false
        }));

        uint256 id = records.length - 1;
        patientRecords[patient].push(id);
        emit RecordUploaded(patient, msg.sender, cid, block.timestamp);
        // actor = provider, subject = patient. No counterparty: address == 0
        auditLog.logEvent(msg.sender, patient, address(0), "UPLOAD_RECORD");
        return id;
    }

    function updateRecord(uint256 previousId, string calldata cid) external returns (uint256) {
        // Check valid id, isn't already superseded, access permission
        require(previousId < records.length, "RecordManager: invalid record id");
        Record storage prev = records[previousId];
        require(!prev.superseded, "RecordManager: previous already superseded");
        require(
            accessControl.checkAccess(prev.patient, msg.sender),
            "RecordManager: not authorized"
        );

        address patient = prev.patient;
        // mark previous as superseded
        prev.superseded = true;

        records.push(Record({
            provider: msg.sender,
            patient: patient,
            cid: cid,
            timestamp: block.timestamp,
            previousVersion: previousId,
            superseded: false
        }));

        uint256 newId = records.length - 1;
        patientRecords[patient].push(newId);
        emit RecordUpdated(newId, previousId, patient, cid, block.timestamp);
        auditLog.logEvent(msg.sender, patient, address(0), "UPDATE_RECORD");
        return newId;
    }

    function getRecord(uint256 id) external view returns (Record memory) {
        require(id < records.length, "RecordManager: invalid id");
        Record memory r = records[id];
        require(
            msg.sender == r.patient ||
            accessControl.checkAccess(r.patient, msg.sender),
            "RecordManager: not authorized to view"
        );
        return r;
    }

    function recordCount() external view returns (uint256) {
        return records.length;
    }
}

contracts/AccessControl.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IPatientRegistry {
    function isPatient(address addr) external view returns (bool);
}

interface IProviderRegistry {
    function isActiveProvider(address addr) external view returns (bool);
}

interface IAuditLog {
    function logEvent(address actor, address subject, address counterparty, string calldata action) external;
}

contract AccessControl {
    IPatientRegistry  public patientRegistry;
    IProviderRegistry public providerRegistry;
    IAuditLog         public auditLog;

    // permissions mapping: patient => provider => granted?
    mapping(address => mapping(address => bool)) private permissions;

    event AccessGranted(address indexed patient, address indexed provider, uint256 timestamp);
    event AccessRevoked(address indexed patient, address indexed provider, uint256 timestamp);

    constructor(address _patientRegistry, address _providerRegistry, address _auditLog) {
        require(_patientRegistry != address(0), "AccessControl: zero patientRegistry");
        require(_providerRegistry != address(0), "AccessControl: zero providerRegistry");
        require(_auditLog != address(0), "AccessControl: zero auditLog");
        patientRegistry  = IPatientRegistry(_patientRegistry);
        providerRegistry = IProviderRegistry(_providerRegistry);
        auditLog         = IAuditLog(_auditLog);
    }


    function grantAccess(address provider) external {
        // require patient exists, provider is active, check if access is not already granted
        require(patientRegistry.isPatient(msg.sender), "AccessControl: caller not a patient");
        require(providerRegistry.isActiveProvider(provider), "AccessControl: provider not active");
        require(!permissions[msg.sender][provider], "AccessControl: already granted");

        permissions[msg.sender][provider] = true;

        emit AccessGranted(msg.sender, provider, block.timestamp);
        auditLog.logEvent(msg.sender, msg.sender, provider, "GRANT_ACCESS");
    }

    function revokeAccess(address provider) external {
        // require patient exists and provider does not already have access
        require(patientRegistry.isPatient(msg.sender), "AccessControl: caller not a patient");
        require(permissions[msg.sender][provider], "AccessControl: no access to revoke");

        permissions[msg.sender][provider] = false;

        emit AccessRevoked(msg.sender, provider, block.timestamp);
        auditLog.logEvent(msg.sender, msg.sender, provider, "REVOKE_ACCESS");
    }

    function checkAccess(address patient, address provider) external view returns(bool) {
        return permissions[patient][provider] && providerRegistry.isActiveProvider(provider);
    }

}

contracts/ProviderRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract ProviderRegistry {
    address public hospitalAdmin;

    struct Provider {
        address wallet;
        string  name;
        bool    active;
    }

    mapping(address => Provider) private providers;
    address[] private providerList;

    event ProviderRegistered(address indexed provider, string name, uint256 timestamp);
        event ProviderRevoked(address indexed provider, uint256 timestamp);

    modifier onlyAdmin() {
        require(msg.sender == hospitalAdmin, "ProviderRegistry: not hospital admin");
        _;
    }

    constructor(address _hospitalAdmin) {
        require(_hospitalAdmin != address(0), "ProviderRegistry: zero admin");
        hospitalAdmin = _hospitalAdmin;
    }

    function registerProvider(address providerAdd, string calldata name) external onlyAdmin {
        require(providerAdd != address(0), "ProviderRegistry: zero address");
        bool isNew = providers[providerAdd].wallet == address(0);

        providers[providerAdd] = Provider({
            wallet: providerAdd,
            name: name,
            active: true
        });

        if (isNew) providerList.push(providerAdd);
        emit ProviderRegistered(providerAdd, name, block.timestamp);
    }

    function revokeProvider(address providerAdd) external onlyAdmin {
        require(isActiveProvider(providerAdd), "Provider Registry: provider not active");
        providers[providerAdd].active = false;
        emit ProviderRevoked(providerAdd, block.timestamp);
    }

    function isActiveProvider(address addr) public view returns (bool) {
        return providers[addr].active;
    }

    function getProvider(address addr) external view returns (Provider memory) {
        return providers[addr];
    }

    function providerCount() external view returns (uint256) {
        return providerList.length;
    }
}

